    private static final int READ_TIMEOUT = 10000; // 10 seconds
    private static final long MAX_IMAGE_SIZE = 10 * 1024 * 1024; // 10MB

    // Allowed image formats
    private static final Set<String> ALLOWED_CONTENT_TYPES = new HashSet<>(Arrays.asList(
        "image/jpeg", "image/png", "image/gif", "image/webp"
    ));

    // Blocked URL protocols to prevent SSRF attacks
    private static final Set<String> BLOCKED_PROTOCOLS = new HashSet<>(Arrays.asList(
        "file", "ftp", "gopher", "jar", "mailto", "netdoc"
    ));

    public boolean processImageFromUrl(String imageUrl) {
        if (imageUrl == null || imageUrl.trim().isEmpty()) {
            System.err.println("Image URL is null or empty");
            return false;
        }

        // Basic URL validation
        if (!isValidUrl(imageUrl)) {
            System.err.println("Invalid image URL: " + imageUrl);
            return false;
        }

        // Check for blocked protocols to prevent SSRF
        if (isBlockedProtocol(imageUrl)) {
            System.err.println("Blocked protocol in image URL: " + imageUrl);
            return false;
        }

        InputStream inputStream = null;
        try {
            URL url = new URL(imageUrl);
            URLConnection connection = url.openConnection();
            connection.setConnectTimeout(CONNECT_TIMEOUT);
            connection.setReadTimeout(READ_TIMEOUT);

            // Check content type to ensure it's an allowed image type
            String contentType = connection.getContentType();
            if (contentType == null || !ALLOWED_CONTENT_TYPES.contains(contentType.toLowerCase())) {
                System.err.println("Unsupported image content type: " + contentType);
                return false;
            }

            // Check content length to avoid downloading very large images
            int contentLength = connection.getContentLength();
            if (contentLength > 0 && contentLength > MAX_IMAGE_SIZE) {
                System.err.println("Image size exceeds maximum allowed size: " + contentLength + " bytes");
                return false;
            }

            inputStream = connection.getInputStream();
            BufferedImage image = ImageIO.read(inputStream);

            if (image != null) {
                System.out.println("Image processed successfully: " + image.getWidth() + "x" + image.getHeight());
                return true;
            } else {
                System.err.println("Failed to read image from URL: " + imageUrl);
                return false;
            }
        } catch (IOException e) {
            System.err.println("Error processing image from URL: " + imageUrl + " - " + e.getMessage());
            return false;
        } finally {
            if (inputStream != null) {
                try {
                    inputStream.close();
                } catch (IOException e) {
                    System.err.println("Failed to close input stream: " + e.getMessage());
                }
            }
        }
    }

    private boolean isValidUrl(String url) {
        try {
            new URL(url);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private boolean isBlockedProtocol(String url) {
        try {
            String protocol = new URL(url).getProtocol();
            return BLOCKED_PROTOCOLS.contains(protocol.toLowerCase());
        } catch (Exception e) {
            return true; // If we can't parse the URL, block it
        }
    }
}

